-- demo-seed.golden.sql — CHECKED-IN EXPECTED OUTPUT of buildSeedSql(SCENARIOS,
-- 'coach@example.com', 2026-07-22T12:00:00.000Z). Not applied to any database, ever.
--
-- REGENERATING THIS FILE IS A DECISION, NOT A CHORE.
--
-- This is the script the repo owner pastes into the Supabase SQL editor against
-- PRODUCTION, with the dates and the coach email swapped for a real run. A diff
-- here is a diff in that script. Read it line by line and be able to say, for
-- every changed line, what it does to a production refresh — a reordered
-- statement, a dropped column, a widened DELETE and a swapped VALUES position
-- all look like ordinary churn in a diff and are none of them ordinary.
--
-- Do NOT re-record it to make a red test green. Re-record it only after you
-- have read the change and decided the new output is the one you want:
--
--   cd web && npx tsx scripts/seed/golden-seed.ts
--
-- This file pins the ARTIFACT. The invariants it cannot state on its own —
-- best_lap = min of the session's laps, laps belonging to the right session,
-- day INSERTs preceding the sessions that reference them — are asserted
-- separately in src/lib/__tests__/generate-demo-seed.test.ts. Both are load
-- bearing; neither replaces the other.
--
-- ==== generated output begins below this line ====
BEGIN;
-- demo-seed.sql — GENERATED by scripts/seed/generate-demo-seed.ts
-- Generated: 2026-07-22T12:00:00.000Z  Coach: coach@example.com
-- Idempotent: re-run any time to refresh demo dates. Do not edit by hand.
DO $seed_guard$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM coaches WHERE email = 'coach@example.com') THEN
    RAISE EXCEPTION 'Coach % not found — check coaches.email', 'coach@example.com';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM tracks WHERE name = 'Thunderhill Raceway') THEN
    RAISE EXCEPTION 'Track % not found — check tracks.name', 'Thunderhill Raceway';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM tracks WHERE name = 'Sonoma Raceway') THEN
    RAISE EXCEPTION 'Track % not found — check tracks.name', 'Sonoma Raceway';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM tracks WHERE name = 'Buttonwillow Raceway') THEN
    RAISE EXCEPTION 'Track % not found — check tracks.name', 'Buttonwillow Raceway';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM tracks WHERE name = 'Laguna Seca') THEN
    RAISE EXCEPTION 'Track % not found — check tracks.name', 'Laguna Seca';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM tracks WHERE name = 'Streets of Willow') THEN
    RAISE EXCEPTION 'Track % not found — check tracks.name', 'Streets of Willow';
  END IF;
END $seed_guard$;

